    s=igw_rd(d,IGW_STATUS);
    if ((s&IGW_TX_BUSY) || !(s&IGW_QUIET)) {
        igw_wr(d,IGW_CONTROL,0); return IGW_TX_TIMEOUT;
    }
    igw_wr(d,IGW_FEED,0x4b49434bu); igw_wr(d,IGW_CONTROL,1);
    last_feed=igw_now(d); igw_wr(d,IGW_TX_KICK,1);
