_Static_assert(sizeof SdBuffer+sizeof SdFs+sizeof SdBanks<65536u,"SD workspace exceeds 64KiB");

/* rsf_sd_protocol.inc */
/* R23 shared CAN/RS485 protocol using SD generations, not full-file arrays. */
struct rsf_store {
 uint8_t digest[32],expected[32],last_data[RSF_BLOCK],read_data[RSF_BLOCK];
 uint32_t size,next,last_offset;unsigned last_count,unit,phase,valid,last_mode;
 uint64_t token,seen;struct sd_bank *bank;
};
static void rsf_restore(struct rsf_store *s){s->valid=s->bank->valid;s->size=s->bank->valid?s->bank->size:0;memcpy(s->digest,s->bank->digest,32);}
static void rsf_abandon(struct rsf_store *s){(void)sd_close(s->bank);s->phase=RSF_FAILED;rsf_restore(s);}
static void rsf_expire(struct rsf_store *s,uint64_t now){if(s->phase!=RSF_EMPTY&&s->phase!=RSF_FAILED&&now-s->seen>=RSF_IDLE_MS)rsf_abandon(s);}
static int rsf_active(struct rsf_store *s){return s->phase==RSF_WRITING||s->phase==RSF_READING;}
static size_t rsf_handle(struct rsf_store *s,const uint8_t *p,size_t n,uint8_t out[256],uint64_t now){
 struct rsf_packet q;unsigned error=RSF_OK,count=0,length=0;uint32_t offset=0;const uint8_t *payload=NULL;
 if(!rsf_parse(p,n,0,&q)||q.unit!=s->unit)return 0;
 rsf_expire(s,now);offset=q.offset;count=q.count;
 if(!SdReady){error=RSF_STORAGE;goto done;}
 if(q.status||q.op<RSF_PUT||q.op>RSF_ABORT){error=RSF_BAD;goto done;}
 if(q.op==RSF_PUT||q.op==RSF_GET||q.op==RSF_GENERATE){
  if(q.count||(q.op==RSF_PUT?q.length!=32:q.length!=0)||q.offset>RSF_MAX||(q.op==RSF_GET&&q.offset)){error=RSF_BAD;goto done;}
  if(q.token==s->token){
   if(s->phase==RSF_FAILED||s->phase==RSF_EMPTY||q.op!=s->last_mode||(q.op!=RSF_GET&&q.offset!=s->size)||(q.op==RSF_PUT&&memcmp(q.payload,s->expected,32))){error=RSF_CONFLICT;goto done;}
  }else{
   if(rsf_active(s)){error=RSF_BUSY;goto done;}
   if(q.op==RSF_GET&&!s->valid){error=RSF_NO_FILE;goto done;}
   s->token=q.token;s->last_mode=q.op;s->next=0;s->last_count=0;
   if(q.op==RSF_PUT){
    s->size=q.offset;memcpy(s->expected,q.payload,32);
    if(sd_begin(s->bank)){rsf_abandon(s);error=RSF_STORAGE;goto done;}s->phase=RSF_WRITING;
   }else{
    if(q.op==RSF_GENERATE){if(sd_generate(s->bank,q.token,q.offset,s->digest)){rsf_abandon(s);error=RSF_STORAGE;goto done;}rsf_restore(s);}
    if(sd_open_read(s->bank)){rsf_abandon(s);error=RSF_STORAGE;goto done;}rsf_restore(s);s->phase=RSF_READING;
   }
  }
  offset=s->size;if(q.op!=RSF_PUT){payload=s->digest;length=32;}
 }else{
  if(q.token!=s->token||s->phase==RSF_FAILED){error=RSF_SESSION;goto done;}
  if(q.op==RSF_WRITE){
   if(s->phase!=RSF_WRITING||!q.count||q.length!=q.count||q.offset>s->size||q.count>s->size-q.offset){error=RSF_RANGE;goto done;}
   if(q.offset==s->next){
    if(sd_write(s->bank,q.offset,q.payload,q.count)){rsf_abandon(s);error=RSF_STORAGE;goto done;}
    s->last_offset=q.offset;s->last_count=q.count;memcpy(s->last_data,q.payload,q.count);s->next+=q.count;
   }else if(q.offset!=s->last_offset||q.count!=s->last_count||memcmp(s->last_data,q.payload,q.count)){error=RSF_CONFLICT;goto done;}
  }else if(q.op==RSF_READ){
   if(s->phase!=RSF_READING||q.length||!q.count||q.offset>s->size||q.count>s->size-q.offset){error=RSF_RANGE;goto done;}
   if(sd_read(s->bank,q.offset,s->read_data,q.count)){rsf_abandon(s);error=RSF_STORAGE;goto done;}payload=s->read_data;length=q.count;
  }else{
   if(q.length||q.count||q.offset){error=RSF_BAD;goto done;}
   if(q.op==RSF_COMMIT){
    if(s->phase!=RSF_COMMITTED){
     if(s->phase!=RSF_WRITING||s->next!=s->size){error=RSF_INCOMPLETE;goto done;}
     int ret=sd_commit(s->bank,s->size,s->expected,s->digest);
     if(ret){rsf_abandon(s);error=ret==-2?RSF_DIGEST:RSF_STORAGE;goto done;}
     rsf_restore(s);s->phase=RSF_COMMITTED;
    }
    payload=s->digest;length=32;
   }else if(q.op==RSF_CLOSE){
    if(s->phase==RSF_WRITING){error=RSF_INCOMPLETE;goto done;}if(sd_close(s->bank)){rsf_abandon(s);error=RSF_STORAGE;goto done;}s->phase=RSF_EMPTY;
   }else if(q.op==RSF_ABORT)rsf_abandon(s);
  }
 }
 s->seen=sd_now_ms();
done:
 return rsf_frame(out,q.unit,1,q.op,error,q.token,offset,count,payload,length);
}

/* rs_file_service.inc */
/* R23 shared persistent SD files. Bounded static workspace, unchanged UART lease. */
_Static_assert(sizeof(struct rsf_store)*IGW_NODE_COUNT<16384u,"unexpected protocol state size");
static uint64_t sd_now_ms(void){return Microseconds(Now()-BootTick)/1000;}
static struct rsf_store RsFiles[IGW_NODE_COUNT];
static struct {unsigned baud,target;uint64_t changed_after,last_frame;uint64_t token;unsigned unit;} RsFileBus;
static void RsFileInit(void){
 memset(&RsFileBus,0,sizeof RsFileBus);RsFileBus.baud=9600;
 int storage=sd_storage_init();
 for(unsigned i=0;i<IGW_NODE_COUNT;i++){memset(RsFiles+i,0,sizeof RsFiles[i]);RsFiles[i].unit=IGW_FIRST_NODE+i;RsFiles[i].bank=SdBanks+i;rsf_restore(RsFiles+i);}
 IGW_LOG("[SD-R23] MOUNT=%s drive=1: directory=IGW23 FatFs=86631 max=%u last_fresult=%u reason=%s\r\n",storage?"FAIL":"PASS",RSF_MAX,(unsigned)SdLast,SdReason);
 for(unsigned i=0;i<IGW_NODE_COUNT;i++)IGW_LOG("[SD-R23] unit=%u valid=%u bytes=%u generation=%llu slot=%c\r\n",RsFiles[i].unit,SdBanks[i].valid,SdBanks[i].size,(unsigned long long)SdBanks[i].generation,SdBanks[i].slot?'B':'A');
 IGW_LOG("[FILE-R24-EXPERIMENT] shared SD file banks; block=192 baud=9600/115200/230400; no RAM fallback; storage=%s\r\n",SdReady?"READY":"UNAVAILABLE");
}
static void RsFileTick(void){
 uint64_t now=Microseconds(Now()-BootTick)/1000;
 for(unsigned i=0;i<IGW_NODE_COUNT;i++)rsf_expire(RsFiles+i,now);
 if(RsFileBus.baud!=9600&&now-RsFileBus.last_frame>=RSF_IDLE_MS){RsFileBus.target=9600;RsFileBus.changed_after=now;}
 if(RsFileBus.target&&now>=RsFileBus.changed_after&&!RtuTx.phase&&!(igw_rd(&Rtu,IGW_STATUS)&IGW_TX_BUSY)&&(igw_rd(&Rtu,IGW_STATUS)&IGW_QUIET)){
  unsigned target=RsFileBus.target;
  if(igw_configure(&Rtu,target)==IGW_OK){RsFileBus.baud=target;RsFileBus.target=0;RsFileBus.last_frame=now;}
 }
}
static size_t RsFileReceive(const uint8_t *p,size_t n,uint8_t out[256]){
 struct rsf_packet q;if(!rsf_parse(p,n,0,&q))return 0;
 int i=igw_node_index(q.unit);if(i<0)return 0;
 uint64_t now=Microseconds(Now()-BootTick)/1000;
 if(RsFileBus.target)return 0; /* no traffic during the explicit switch guard */
 if(q.op==RSF_SPEED){
  unsigned error=RSF_OK;
  if(q.status||q.length||q.count||(q.offset!=9600&&q.offset!=115200&&q.offset!=230400))error=RSF_BAD;
  for(unsigned k=0;k<IGW_NODE_COUNT;k++){rsf_expire(RsFiles+k,now);if(rsf_active(RsFiles+k))error=RSF_BUSY;}
  if(!error){RsFileBus.target=q.offset;RsFileBus.changed_after=now+100;RsFileBus.token=q.token;RsFileBus.unit=q.unit;RsFileBus.last_frame=now;}
  return rsf_frame(out,q.unit,1,q.op,error,q.token,q.offset,0,NULL,0);
 }
 size_t reply=rsf_handle(RsFiles+i,p,n,out,now);
 if(reply)RsFileBus.last_frame=now;
 return reply;
}

/* cbf_protocol.h */
#ifndef CBF_PROTOCOL_H
#define CBF_PROTOCOL_H

/* Classic-CAN bounded-credit transport for one CRC-protected RSF packet.
 * Four 5-byte fragments per credit group; no unbounded hardware queue burst.
 * Full 32-bit message ID in control; low 16 bits + fragment index in data.
 * Complete file token/offset and SHA-256 remain in the upper protocol. */
#define CBF_CTL 0x680u
#define CBF_REPLY 0x6a0u
#define CBF_DATA 0x700u
#define CBF_RDATA 0x720u
#define CBF_WINDOW 4u
#define CBF_PAYLOAD 5u
#define CBF_PACKET (RSF_HEAD+RSF_BLOCK+2u)
enum {CBF_BEGIN=0xa0,CBF_ACK=0xa1,CBF_PULL=0xa2,CBF_META=0xa3,CBF_END=0xa4,CBF_ERROR=0xaf};
struct cbf_frame {uint32_t id;uint8_t data[8];};
struct cbf_store {unsigned unit,length,next,reply_length,cached,active,tail_crc;uint32_t message;uint64_t seen;uint8_t request[CBF_PACKET],reply[256];struct cbf_frame queued[CBF_WINDOW+1];unsigned q_head,q_count;};
static inline unsigned cbf_fragments(unsigned bytes){return (bytes+CBF_PAYLOAD-1)/CBF_PAYLOAD;}
static inline void cbf_control(uint8_t out[8],unsigned type,uint32_t id,unsigned index,unsigned status){memset(out,0,8);out[0]=(uint8_t)type;rsf_p32(out+1,id);out[5]=(uint8_t)index;out[6]=(uint8_t)(index>>8);out[7]=(uint8_t)status;}
static inline void cbf_data(uint8_t out[8],uint32_t id,unsigned index,const uint8_t *p,unsigned size){
 memset(out,0,8);out[0]=(uint8_t)id;out[1]=(uint8_t)(id>>8);out[2]=(uint8_t)index;unsigned start=index*CBF_PAYLOAD,n=size-start;if(n>CBF_PAYLOAD)n=CBF_PAYLOAD;memcpy(out+3,p+start,n);
}
static inline void cbf_enqueue(struct cbf_store *s,unsigned data,const uint8_t p[8]){
 if(s->q_count>=CBF_WINDOW+1)return;
 struct cbf_frame *f=s->queued+s->q_count++;f->id=(data?CBF_RDATA:CBF_REPLY)+s->unit;memcpy(f->data,p,8);
}
static inline void cbf_status(struct cbf_store *s,unsigned type,unsigned index,unsigned status){uint8_t p[8];cbf_control(p,type,s->message,index,status);cbf_enqueue(s,0,p);}
/* The caller drains queued frames before accepting another control request.
 * A transport retry never re-executes an already cached application packet. */
static inline int cbf_receive(struct cbf_store *s,struct rsf_store *file,unsigned data,const uint8_t p[8],uint64_t now){
 if(s->q_head<s->q_count){return 0;}s->q_head=s->q_count=0;
 if(!data){
  uint32_t id=rsf_u32(p+1);if(!id)return 1;
  if(p[0]==CBF_BEGIN){
   unsigned n=p[5],crc=rsf_u16(p+6);if(n<RSF_HEAD+2||n>CBF_PACKET)return 1;
   if(id==s->message){
    if(n!=s->length||crc!=s->tail_crc){cbf_status(s,CBF_ERROR,0,RSF_CONFLICT);return 1;}
    if(!s->cached&&now-s->seen>=2000){s->next=0;s->active=1;}
   }else{s->message=id;s->length=n;s->tail_crc=crc;s->next=0;s->cached=0;s->active=1;s->reply_length=0;}
   s->seen=now;cbf_status(s,CBF_ACK,s->next,CBF_WINDOW);return 1;
  }
  if(p[0]!=CBF_PULL||id!=s->message||!s->cached||p[7])return 1;
  unsigned index=rsf_u16(p+5);
  if(index==65535u){cbf_status(s,CBF_META,s->reply_length,0);return 1;}
  unsigned count=cbf_fragments(s->reply_length);if(index>=count){cbf_status(s,CBF_ERROR,index,RSF_RANGE);return 1;}
  unsigned end=index+CBF_WINDOW;if(end>count)end=count;
  for(unsigned i=index;i<end;i++){uint8_t wire[8];cbf_data(wire,s->message,i,s->reply,s->reply_length);cbf_enqueue(s,1,wire);}
  cbf_status(s,CBF_END,end,0);return 1;
 }
 if(!s->active||rsf_u16(p)!=(s->message&65535u))return 1;
 unsigned index=p[2],count=cbf_fragments(s->length);if(index>=count)return 1;
 unsigned start=index*CBF_PAYLOAD,n=s->length-start;if(n>CBF_PAYLOAD)n=CBF_PAYLOAD;
 for(unsigned i=n;i<CBF_PAYLOAD;i++)if(p[3+i])return 1;
 if(index>s->next){cbf_status(s,CBF_ACK,s->next,CBF_WINDOW);return 1;}
 if(index<s->next){
  if(memcmp(s->request+start,p+3,n)){s->active=0;cbf_status(s,CBF_ERROR,index,RSF_CONFLICT);return 1;}
 }else{memcpy(s->request+start,p+3,n);s->next++;}
 s->seen=now;
 if(s->next==count&&!s->cached){
  struct rsf_packet q;
  if(rsf_u16(s->request+s->length-2)!=s->tail_crc||!rsf_parse(s->request,s->length,0,&q)||q.unit!=s->unit){s->active=0;cbf_status(s,CBF_ERROR,index,RSF_BAD);return 1;}
  s->reply_length=(unsigned)rsf_handle(file,s->request,s->length,s->reply,now);
  if(!s->reply_length){s->active=0;cbf_status(s,CBF_ERROR,index,RSF_BAD);return 1;}s->cached=1;
 }
 if((index+1)%CBF_WINDOW==0||index+1==count)cbf_status(s,CBF_ACK,s->next,CBF_WINDOW);
 return 1;
}
static inline const struct cbf_frame *cbf_peek(struct cbf_store *s){return s->q_head<s->q_count?s->queued+s->q_head:NULL;}
static inline void cbf_sent(struct cbf_store *s){if(s->q_head<s->q_count)s->q_head++;}
#endif

/* can_block_service.inc */
/* Uses the R23 persistent SD file banks: CAN and RS485 read/write the same committed
 * file. Legacy R18 64KiB CAN slots remain independent for compatibility. */
static struct cbf_store CanBlocks[IGW_NODE_COUNT];
static unsigned CanBlockNext;
static AL_U64 CanBlockPendingSince;
static void CanBlockInit(void){
 memset(CanBlocks,0,sizeof CanBlocks);CanBlockNext=0;CanBlockPendingSince=0;
 for(unsigned i=0;i<IGW_NODE_COUNT;i++)CanBlocks[i].unit=IGW_FIRST_NODE+i;
 IGW_LOG("[FILE-R23] classic CAN block192 credit4 max=%u shared CAN/RS485 bytes/node; control=0x680+unit reply=0x6a0+unit data=0x700+unit reply_data=0x720+unit\r\n",RSF_MAX);
}
static int CanBlockPending(void){for(unsigned i=0;i<IGW_NODE_COUNT;i++)if(cbf_peek(CanBlocks+i))return 1;return 0;}
static int CanBlockTxTick(void){
 for(unsigned b=0;b<IGW_NODE_COUNT;b++){
  unsigned i=CanBlockNext;CanBlockNext=(CanBlockNext+1)%IGW_NODE_COUNT;const struct cbf_frame *f=cbf_peek(CanBlocks+i);if(!f)continue;
  if(!CanBlockPendingSince)CanBlockPendingSince=Now();
  AL_CAN_FrameStruct tx;memset(&tx,0,sizeof tx);tx.BufferMode=AL_CAN_BUFFER_MODE_PTB;tx.Id=f->id;tx.DataLen=AL_CAN_LEN_8;
  for(unsigned k=0;k<8;k++)tx.Data[k/4]|=(AL_U32)f->data[k]<<(8*(k%4));
  AL_S32 ret=AlCan_Hal_SendFrame(Can,&tx);
  if(ret==AL_OK){cbf_sent(CanBlocks+i);++Stats.tx;CanBlockPendingSince=0;}
  else if((ret!=AL_CAN_ERR_TP_BUSY&&ret!=AL_CAN_ERR_IN_TS_FULL&&ret!=AL_CAN_ERR_BUSY)||Now()-CanBlockPendingSince>=Budget(WAIT_MS)){
   ++Stats.tx_fail;CanBlocks[i].q_head=CanBlocks[i].q_count;CanBlockPendingSince=0;
  }
  return 1;
 }
 return 0;
}
static int CanBlockReceive(const AL_CAN_FrameStruct *f){
 unsigned data=0,unit=0;
 if(f->Id>CBF_CTL&&f->Id<=CBF_CTL+16)unit=f->Id-CBF_CTL;
 else if(f->Id>CBF_DATA&&f->Id<=CBF_DATA+16){unit=f->Id-CBF_DATA;data=1;}
 else return 0;
 int i=igw_node_index(unit);if(i<0)return 1;
 if(f->DataLen!=AL_CAN_LEN_8||f->IsIdExt||f->IsRemote||f->IsBitSwitch||f->Koer!=AL_CAN_KOER_NONE)return 1;
 uint8_t p[8];for(unsigned k=0;k<8;k++)p[k]=(uint8_t)(f->Data[k/4]>>(8*(k%4)));
 cbf_receive(CanBlocks+i,RsFiles+i,data,p,Microseconds(Now()-BootTick)/1000);return 1;
}

/* slave.inc */
static struct igw_nodes Nodes;
static struct {AL_BOOL pending;AL_CAN_FrameStruct frame;AL_U64 started;} CanReply;
static struct ul_client Uplink[IGW_NODE_COUNT];
static unsigned UplinkNext,RsUplinkNext;
static struct rsu_client RsUplink[IGW_NODE_COUNT];
static unsigned RsUplinkTx;
static uint64_t UplinkMs(void){return Microseconds(Now()-BootTick)/1000;}
#define BIDIR_R26_VERSION 0x1a26u
#define BIDIR_R26_MANUAL 0xa526u
static uint16_t UplinkSource(unsigned i,uint64_t now){
    uint16_t value=Nodes.regs[i][28]==BIDIR_R26_MANUAL?Nodes.regs[i][30]:(uint16_t)((IGW_FIRST_NODE+i)*1000u+now/1000);
    Nodes.regs[i][11]=value;return value; /* device counter or configured demo value */
}
static void UplinkInit(void){
    UplinkNext=RsUplinkNext=RsUplinkTx=0;uint64_t now=UplinkMs();
    for(unsigned i=0;i<IGW_NODE_COUNT;i++){Nodes.regs[i][13]=BIDIR_R26_VERSION;Nodes.regs[i][27]=Nodes.regs[i][28]=0;ul_client_init(Uplink+i,IGW_FIRST_NODE+i,now);rsu_init(RsUplink+i,IGW_FIRST_NODE+i);}
    IGW_LOG("[BIDIR-R26] configured periodic uplink; CAN mode R28 value R30; RS485 mode R27 value R29; volatile 16-bit\r\n");
}
static int UplinkReceive(const AL_CAN_FrameStruct *f){
    unsigned unit=f->Id>UL_WELCOME&&f->Id<=UL_WELCOME+16?f->Id-UL_WELCOME:
        f->Id>UL_ACK&&f->Id<=UL_ACK+16?f->Id-UL_ACK:
        f->Id>RSU_GRANT&&f->Id<=RSU_GRANT+16?f->Id-RSU_GRANT:
        f->Id>RSU_ACK&&f->Id<=RSU_ACK+16?f->Id-RSU_ACK:
        f->Id>RSU_RELEASED&&f->Id<=RSU_RELEASED+16?f->Id-RSU_RELEASED:
        f->Id>RSU_CANCEL&&f->Id<=RSU_CANCEL+16?f->Id-RSU_CANCEL:0;
    int i=igw_node_index(unit);if(i<0)return 0;
    if(f->DataLen!=AL_CAN_LEN_8||f->IsIdExt||f->IsRemote||f->IsBitSwitch||f->Koer!=AL_CAN_KOER_NONE)return 1;
    struct ul_frame frame;frame.id=f->Id;
    for(unsigned b=0;b<8;b++)frame.data[b]=(uint8_t)(f->Data[b/4]>>(8*(b%4)));
    uint64_t now=UplinkMs();if(f->Id>RSU_GRANT){rsu_receive(RsUplink+i,&frame,now);return 1;}
    ul_client_receive(Uplink+i,&frame,now,UplinkSource((unsigned)i,now));return 1;
}
static void UplinkTick(void){
    if(CanReply.pending)return; /* existing command responses have priority */
    uint64_t now=UplinkMs();
    for(unsigned budget=0;budget<IGW_NODE_COUNT;budget++){
        unsigned i=UplinkNext;UplinkNext=(UplinkNext+1)%IGW_NODE_COUNT;
        struct ul_client candidate=Uplink[i];struct ul_frame frame;
        if(!ul_client_tick(&candidate,now,UplinkSource(i,now),&frame)){Uplink[i]=candidate;continue;}
        AL_CAN_FrameStruct tx;memset(&tx,0,sizeof tx);tx.BufferMode=AL_CAN_BUFFER_MODE_PTB;
        tx.Id=frame.id;tx.DataLen=AL_CAN_LEN_8;
        for(unsigned b=0;b<8;b++)tx.Data[b/4]|=(AL_U32)frame.data[b]<<(8*(b%4));
        if(AlCan_Hal_SendFrame(Can,&tx)==AL_OK)Uplink[i]=candidate;
        return; /* bounded, no UART/CAN busy wait */
    }
}
static void RsUplinkTick(void){
    uint64_t now=UplinkMs();
    for(unsigned b=0;b<IGW_NODE_COUNT;b++){
        unsigned i=RsUplinkNext;RsUplinkNext=(RsUplinkNext+1)%IGW_NODE_COUNT;
        struct rsu_client *c=RsUplink+i;uint8_t frame[RSU_BYTES];
        if(c->cancelled&&RsUplinkTx==i+1){
            igw_wr(&Rtu,IGW_CONTROL,0);
            if(RtuTx.phase==1){RtuTx.phase=0;RsUplinkTx=0;}
        }
        if(!RtuTx.phase && !(igw_rd(&Rtu,IGW_STATUS)&IGW_RX_READY) && rsu_prepare(c,now,frame)){
            if(RtuTxBegin(frame,sizeof frame)==IGW_OK){
                /* Absolute deadlines retain the original grant receipt time. */
                AL_U64 origin=BoardUs(NULL)-(now-c->grant_ms)*1000ULL;
                RtuTx.latest_start=origin+RSU_START_MS*1000ULL;
                RtuTx.latest_finish=origin+RSU_TX_LIMIT_MS*1000ULL;RsUplinkTx=i+1;
            }
        }
        if(CanReply.pending)continue;
        if(c->seq==65535u&&!c->pending)ul_connect(Uplink+i,now);
        struct rsu_client candidate=*c;struct ul_frame f;
        uint32_t epoch=Uplink[i].phase==UL_CONNECT?0:Uplink[i].epoch;
        uint16_t source=Nodes.regs[i][27]==BIDIR_R26_MANUAL?Nodes.regs[i][29]:(uint16_t)((IGW_FIRST_NODE+i)*1000u+now/1000);
        Nodes.regs[i][12]=source;
        int release=0;
        if(!RtuTx.phase && !(igw_rd(&Rtu,IGW_STATUS)&IGW_TX_BUSY) && (igw_rd(&Rtu,IGW_STATUS)&IGW_QUIET))release=rsu_release_tick(&candidate,now,&f);
        if(!release&&!rsu_tick(&candidate,now,epoch,source,&f)){*c=candidate;continue;}
        AL_CAN_FrameStruct tx;memset(&tx,0,sizeof tx);tx.BufferMode=AL_CAN_BUFFER_MODE_PTB;
        tx.Id=f.id;tx.DataLen=AL_CAN_LEN_8;
        for(unsigned k=0;k<8;k++)tx.Data[k/4]|=(AL_U32)f.data[k]<<(8*(k%4));
        if(AlCan_Hal_SendFrame(Can,&tx)==AL_OK)*c=candidate;
        return;
    }
}
static void CanTick(void)
{
    if(CanReply.pending){
        AL_S32 ret=AlCan_Hal_SendFrame(Can,&CanReply.frame);
        if(ret==AL_OK){++Stats.tx;++Stats.ok;CanReply.pending=AL_FALSE;}
        else if((ret!=AL_CAN_ERR_TP_BUSY && ret!=AL_CAN_ERR_IN_TS_FULL && ret!=AL_CAN_ERR_BUSY) ||
                Now()-CanReply.started>=Budget(WAIT_MS)){++Stats.tx_fail;CanReply.pending=AL_FALSE;}
    }
    if(CanReply.pending)return;
    if(CanBlockTxTick())return;
    for(unsigned i=0;i<4;++i){
        AL_CAN_FrameStruct request;AL_S32 ret=Receive(&request);
        if(ret==AL_CAN_ERR_RECV_EMPTY)break;
        if(ret!=AL_OK)break;
        if(CanBlockReceive(&request)){if(CanBlockPending())break;continue;}
        if(FileReceive(&request,&CanReply.frame)){
            ++Stats.attempts;CanReply.pending=AL_TRUE;CanReply.started=Now();break;
        }
        if(UplinkReceive(&request))continue;
        if(request.Id>=0x211 && request.Id<=0x220 && igw_node_index(request.Id-0x210)>=0) {
            if(request.DataLen!=AL_CAN_LEN_8 || request.IsIdExt || request.IsRemote ||
               request.IsBitSwitch || request.Koer!=AL_CAN_KOER_NONE) {++Stats.bad_request;continue;}
            uint8_t p[8],out[8];
            for(unsigned b=0;b<8;b++)p[b]=(uint8_t)(request.Data[b/4]>>(8*(b%4)));
            int reply_id=igw_nodes_can(&Nodes,request.Id,p,out,Microseconds(Now()-BootTick));
            memset(&CanReply.frame,0,sizeof CanReply.frame);
            CanReply.frame.BufferMode=AL_CAN_BUFFER_MODE_PTB;
            CanReply.frame.Id=(AL_U32)reply_id;CanReply.frame.DataLen=AL_CAN_LEN_8;
            for(unsigned b=0;b<8;b++)CanReply.frame.Data[b/4]|=(AL_U32)out[b]<<(8*(b%4));
            ++Stats.attempts;CanReply.pending=AL_TRUE;CanReply.started=Now();break;
        }
        if(request.Id!=REQUEST_ID || igw_node_index(1)<0){++Stats.ignored;continue;}
        if(!Valid(&request,REQUEST_TAG)){++Stats.bad_request;continue;}
        ++Stats.attempts;Frame(&CanReply.frame,REPLY_ID,request.Data[0],REPLY_TAG);
        CanReply.pending=AL_TRUE;CanReply.started=Now();break;
    }
}
static void RtuTick(void)
{
    if(RtuTx.phase){int done=RtuTxTick();
        if(RsUplinkTx){if(done){rsu_done(RsUplink+RsUplinkTx-1,UplinkMs());RsUplinkTx=0;}} /* Separate upload statistics, no false Modbus completions. */
        else if(done<0)++RtuStats.tx_fail;else if(done>0)++RtuStats.ok;
        return;}
    uint8_t rx[256],reply[256];size_t n=0;uint64_t ticks=0;
    int got=igw_take_frame(&Rtu,rx,&n,&ticks);
    if(got<0){++RtuStats.sw_bad;return;}if(got==0)return;
    if(n && igw_node_index(rx[0])>=0)++RtuStats.attempts;
    size_t length=(n>1 && rx[1]==0x42)?RsFileReceive(rx,n,reply):igw_nodes_rtu(&Nodes,rx,n,reply,Microseconds(Now()-BootTick));
    if(length && RtuTxBegin(reply,length)!=IGW_OK)++RtuStats.tx_fail;
}
/* R17.2: sampling remains active; synchronous batch UART output is opt-in.
 * No wire protocol, bus ownership, timeout or device register changes. */
#ifndef IGW_RUNTIME_LOGGING
#define IGW_RUNTIME_LOGGING 0
#endif
#if IGW_RUNTIME_LOGGING != 0 && IGW_RUNTIME_LOGGING != 1
#error "IGW_RUNTIME_LOGGING must be 0 or 1"
#endif
static void RuntimeTelemetryStep(AL_U64 *last_log)
{
    if(Now()-*last_log<Budget(5000) || CanReply.pending || RtuTx.phase)return;
    if(IGW_RUNTIME_LOGGING){Summary();RtuSummary();
            for(unsigned i=0;i<IGW_NODE_COUNT;i++)IGW_LOG("[UPLINK] unit=%u acked=%llu retries=%llu unknown=%llu reconnects=%llu\r\n",IGW_FIRST_NODE+i,(unsigned long long)Uplink[i].acked,(unsigned long long)Uplink[i].retries,(unsigned long long)Uplink[i].unknown,(unsigned long long)Uplink[i].reconnects);
            for(unsigned i=0;i<IGW_NODE_COUNT;i++)IGW_LOG("[RS-UPLINK] unit=%u acked=%llu retries=%llu unknown=%llu expired=%llu\r\n",IGW_FIRST_NODE+i,(unsigned long long)RsUplink[i].accepted,(unsigned long long)RsUplink[i].retries,(unsigned long long)RsUplink[i].unknown,(unsigned long long)RsUplink[i].expired);
            IGW_LOG("[DUAL-SLAVE] %s; CAN ok is reply-submit, check master/PC\r\n",(Clean()&&RtuClean())?"CLEAN":"REVIEW");
    }else{
        Snapshot(AL_FALSE); /* Preserve REC/TEC/max/error accumulation without UART. */
    }
    *last_log=Now();
}
static void RunDual(void)
{
    IGW_LOG("[DUAL-SLAVE] R21 READY first_node=%u nodes=%u; independent banks; CAN request=0x210+unit reply=0x190+unit; RS485 FC03+FC06 9600 8E1\r\n",IGW_FIRST_NODE,IGW_NODE_COUNT);
    IGW_LOG("[UPLINK] R17 CAN host R16; RS485 host R17 with CAN RTS/GRANT/ACK, 2s generated counters; no unsolicited RS485 without lease\r\n");
    IGW_LOG("[RUN-LOG] R21 periodic_uart=%u; control_protocol=R17; file_protocol=R18; startup logs retained\r\n",(unsigned)IGW_RUNTIME_LOGGING);
    AL_U64 last_log=Now();
    for(;;){
        CanTick();RsFileTick();RtuTick();UplinkTick();RsUplinkTick();
        RuntimeTelemetryStep(&last_log);
#ifdef IGW_HOST_TEST
        if(Stats.ok>=100 && RtuStats.ok>=100)break;
#endif
    }
}

/* main.inc */
AL_S32 main(AL_VOID)
{
    memset(&Stats,0,sizeof Stats);memset(&RtuStats,0,sizeof RtuStats);memset(&RtuTx,0,sizeof RtuTx);
    AlLog_SetLevel(AL_LOG_LEVEL_NOTICE);Can=AL_NULL;
    IGW_LOG("\r\n[IGW-DUAL] gateway SD_FILE_R23 role=%s CAN(v1.2)+RS485+UDP\r\n",IGW_CAN_MASTER?"MASTER":"SLAVE");
    IGW_LOG("[PLATFORM] HPF=%s BIT_METADATA=%s\r\n",HPF_EXPORT_TIME,BITSTREAM_GENERATE_TIME);
    AL_S32 ret=Setup();if(ret!=AL_OK)goto stop;
    BootTick=Now();for(unsigned i=0;i<100;++i)(void)Now();
    if(Now()==BootTick){++Stats.timer_error;ret=(AL_S32)AL_CAN_ERR_ILLEGAL_PARAM;goto stop;}
    memset(&Rtu,0,sizeof Rtu);Rtu.read=BoardRead;Rtu.write=BoardWrite;Rtu.now_us=BoardUs;
    IGW_LOG("[PL-RS485] magic=0x%08x version=0x%08x clock=%u Hz\r\n",
        igw_rd(&Rtu,IGW_MAGIC),igw_rd(&Rtu,IGW_VERSION),igw_rd(&Rtu,IGW_CLOCK));
    ret=(AL_S32)igw_configure(&Rtu,9600);if(ret!=IGW_OK)goto stop;
    RtuBaseline=igw_get_counters(&Rtu);
    IGW_LOG("[RS485-CONFIG] 9600 8E1 multi-node base=0x80100000 div=%u\r\n",igw_rd(&Rtu,IGW_DIV));
#if IGW_CAN_MASTER
    memset(&Net,0,sizeof Net);memset(&CanJob,0,sizeof CanJob);memset(&RtuJob,0,sizeof RtuJob);PollEnabled=AL_FALSE;
    Udp=AL_NULL;ret=NetworkInit();if(ret!=AL_OK)goto stop;
#else
    memset(&CanReply,0,sizeof CanReply);igw_nodes_init(&Nodes);UplinkInit();FileInit();RsFileInit();CanBlockInit();
#endif
    RunDual();return AL_OK;
stop:
    IGW_LOG("[FATAL] dual init ret=0x%08x; no polling started\r\n",(AL_U32)ret);
    if(Can)AlCan_ll_SetCanCtrlReset(Can->Dev.BaseAddr,AL_TRUE);
#ifndef IGW_HOST_TEST
    for(;;)AlSys_MDelay(1000);
#endif
    return ret;
}
